import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Badge,
  Card,
  Table,
  Container,
  Row,
  Col,
  Button,
} from "react-bootstrap";
import "chartist/dist/chartist.min.css";

const themeStyle = `
  body { 
    background-color: #f8f9fc !important; 
    font-family: 'Inter', 'Kanit', sans-serif; 
    color: #4a5568;
  }
  
  .header-purple-bg { 
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important; 
    padding-top: 1rem; 
    padding-bottom: 8rem; 
    margin-bottom: -6rem;
    box-shadow: 0 4px 20px rgba(118, 75, 162, 0.2);
  }

  .card { 
    border: 1px solid rgba(118, 75, 162, 0.1); 
    border-radius: 1.25rem; 
    box-shadow: 0 10px 25px rgba(118, 75, 162, 0.05);
    margin-bottom: 1.5rem;
    background: #fff;
    overflow: hidden;
  }
  
  .card-accent-purple { border-top: 5px solid #764ba2; }

  /* วงกลมล้อมรอบไอคอนรถบัส */
  .icon-circle {
    width: 60px;
    height: 60px;
    background-color: #f3f0ff;
    border: 2px solid #764ba2;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 4px 10px rgba(118, 75, 162, 0.15);
    transition: transform 0.3s ease;
  }

  .card:hover .icon-circle {
    transform: scale(1.1) rotate(5deg);
  }

  .btn-station {
    flex: 0 0 auto;
    padding: 10px 20px;
    border-radius: 12px !important; 
    font-weight: 600;
    transition: all 0.3s ease;
    background-color: #ffffff;
    border: 2px solid #edf2f7;
    color: #718096;
    margin-right: 8px;
  }

  .btn-station.active {
    background-color: #764ba2;
    border-color: #764ba2;
    color: #ffffff !important;
    box-shadow: 0 4px 12px rgba(118, 75, 162, 0.25);
  }

  .station-scroll-container {
    display: flex;
    overflow-x: auto;
    padding: 10px 0;
    scrollbar-width: none;
  }
  .station-scroll-container::-webkit-scrollbar { display: none; }

  .table-clean thead th {
    background-color: #f3f0ff;
    color: #6b46c1;
    text-transform: uppercase;
    font-size: 0.75rem;
    font-weight: 700;
    padding: 1rem 1.25rem;
  }

  .badge-soft-success { background-color: #d1fae5; color: #065f46; border-radius: 8px; padding: 6px 12px; border: none; }
  .badge-soft-danger { background-color: #fee2e2; color: #991b1b; border-radius: 8px; padding: 6px 12px; border: none; }

  .chart-scroll { overflow-x:auto; overflow-y:hidden; }
`;

function Dashboard() {
  const [tableData, setTableData] = useState([]);
  const [chartData, setChartData] = useState({ labels: [], series: [] });
  const [selectedStation, setSelectedStation] = useState(0);
  const [stats, setStats] = useState({ busStops: 0 });

  const stationNames = ["วิศวะ", "วิทยาศาสตร์", "ศิลปศาสตร์", "PKY"];

  const fetchData = async () => {
    try {
      const statsRes = await fetch("http://localhost:3000/api/dashboard-stats");
      const statsJson = await statsRes.json();
      setStats({ busStops: statsJson.capacity || 0 });

      const tableRes = await fetch("http://localhost:3000/api/table-data");
      const tableJson = await tableRes.json();
      setTableData(Array.isArray(tableJson) ? tableJson : tableJson.data || []);

      const chartRes = await fetch("http://localhost:3000/api/chart-data");
      const chartJson = await chartRes.json();
      setChartData({ labels: chartJson.labels || [], series: chartJson.series || [] });
    } catch (err) {
      console.error("Fetch error:", err);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 10000);
    return () => clearInterval(interval);
  }, []);

  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      const color = data.value.y > 20 ? "#f5365c" : "#2dce89";
      data.element.attr({ style: `stroke: ${color}; stroke-width: 30px;` });
      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 15,
        style: "font-size:14px;fill:#4a5568;font-weight:bold;text-anchor:middle",
      }).text(data.value.y);
    }
  };

  return (
    <>
      <style>{themeStyle}</style>
      <div style={{ minHeight: "100vh" }}>
        <div className="header-purple-bg">
          <Container fluid className="px-4">
            <h2 className="text-white fw-bold mb-0">ข้อมูลรายวัน</h2>
          </Container>
        </div>

        <Container fluid className="px-4">
          <Row>
            <Col lg="3" md="6">
              <Card className="border-0 shadow-sm">
                <Card.Body className="d-flex justify-content-between align-items-center p-4">
                  <div>
                    <p className="text-uppercase text-muted small fw-bold mb-1">จุดจอดรถทั้งหมด</p>
                    <h3 className="fw-bold mb-0 text-dark">
                      {stats.busStops} <small className="text-muted fw-normal fs-6"></small>
                    </h3>
                  </div>
                  <div className="icon-circle">
                    <span style={{ fontSize: '28px' }}>🚌</span>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>

          <Row className="mt-2">
            <Col xs="12">
              <Card className="card-accent-purple shadow-sm">
                <Card.Header className="bg-white border-0 pt-4">
                  <Card.Title as="h5" className="fw-bold text-dark m-0">สถานะเรียลไทม์</Card.Title>
                </Card.Header>
                <Card.Body className="p-0 mt-3">
                  <div className="table-responsive">
                    <Table className="table-clean mb-0">
                      <thead>
                        <tr>
                          <th>สถานี</th>
                          <th>ผู้โดยสาร</th>
                          <th>สถานะ</th>
                          <th>อัปเดตล่าสุด</th>
                        </tr>
                      </thead>
                      <tbody>
                        {tableData.map((item, index) => (
                          <tr key={index}>
                            <td className="fw-bold text-dark">{item.stationName}</td>
                            <td>
                              <span className="fs-5 fw-bold">{item.passengerCount}</span> 
                              <small className="text-muted ms-1">คน</small>
                            </td>
                            <td>
                              <Badge className={item.passengerCount > 20 ? "badge-soft-danger" : "badge-soft-success"}>
                                {item.passengerCount > 20 ? "● หนาแน่น" : "● ปกติ"}
                              </Badge>
                            </td>
                            <td className="text-muted small">
                              {item.timestamp ? new Date(item.timestamp).toLocaleTimeString("th-TH") : "-"}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>

          <Row className="mt-3 pb-5">
            <Col xs="12">
              <Card className="shadow-sm">
                <Card.Header className="bg-white border-0 pt-4">
                  <Card.Title as="h5" className="fw-bold">สถิติ: {stationNames[selectedStation]}</Card.Title>
                  <div className="station-scroll-container mt-2">
                    {stationNames.map((name, index) => (
                      <button
                        key={index}
                        onClick={() => setSelectedStation(index)}
                        className={`btn-station ${selectedStation === index ? 'active' : ''}`}
                      >
                        {name}
                      </button>
                    ))}
                  </div>
                </Card.Header>
                <Card.Body>
                  <div className="chart-scroll">
                    <div style={{ width: Math.max(chartData.labels.length * 70, 600), height: "400px" }}>
                      <ChartistGraph
                        data={{ labels: chartData.labels, series: [chartData.series[selectedStation] || []] }}
                        type="Bar"
                        options={{
                          height: "400px",
                          axisX: { showGrid: false, offset: 60 },
                          axisY: { onlyInteger: true, low: 0, high: Math.max(...(chartData.series[selectedStation] || [0])) + 5 },
                          chartPadding: { left: 20, right: 20, top: 40, bottom: 40 },
                          fullWidth: true,
                        }}
                        listener={{ draw: drawBarLabels }}
                      />
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Container>
      </div>
    </>
  );
}

export default Dashboard;
